#!/usr/bin/env bash
# Generate winhttp_shim.def for the winhttp proxy/shim DLL.
#
# The shim ships AS  winhttp.dll  next to the game (WINEDLLOVERRIDES=winhttp=n,b),
# and Proton's builtin winhttp is copied alongside as  winhttp_real.dll  (the
# forward target). Every symbol the game imports must be exported by the shim or
# the game won't load. Functions we intercept (HOOKED) are exported from our own
# object code; everything else is a zero-code loader FORWARD to the real DLL.
set -euo pipefail
cd "$(dirname "$0")"

# The COMPLETE export surface of the builtin winhttp.dll (the forward target),
# not just what the game exe's IAT binds. Other DLLs loaded into the prefix --
# notably EOSSDK-Win64-Shipping.dll -- also import from winhttp, so the shim must
# re-export EVERY builtin symbol or those imports fail to resolve at load.
#
# IMPORTANT: keep real ordinals. Some binaries may import winhttp by ordinal,
# and a plain name-only .def lets the linker assign ordinals from file/order
# details. game_imports.txt may contain either:
#   <ordinal> <name>
# or, for the current Wine/Proton ordered list, just:
#   <name>
# in exact ordinal order starting at 1. Refresh from a real builtin with e.g.:
#   objdump -x <builtin winhttp.dll> | \
#     awk '/Ordinal\/Name Pointer/{p=1;next} p&&/^        \[/{print $3, $5}'
IMPORTS="game_imports.txt"     # full builtin winhttp export surface + ordinals/order
REAL_DLL="winhttp_real"        # forward target module (NO .dll suffix, DOT-FREE)
# NOTE: must be DOT-FREE. The PE loader splits a forwarder string on the LAST '.'
# to separate module from function; a name with a '.' looks like it already has
# an extension and '.dll' is NOT appended -> forward fails -> crash at load.
OUT="winhttp_shim.def"

# Functions we implement ourselves (typed trampolines w/ redirect + logging +
# capture-mode tap). Keep this list in sync with src/trampolines.cpp.
HOOKED=$(cat <<'EOF'
WinHttpConnect
WinHttpOpenRequest
WinHttpAddRequestHeaders
WinHttpSendRequest
WinHttpWriteData
WinHttpReceiveResponse
WinHttpReadData
WinHttpSetStatusCallback
WinHttpCloseHandle
EOF
)

is_hooked() { grep -qxF "$1" <<<"$HOOKED"; }

declare -A SEEN_NAMES=()
declare -A SEEN_ORDINALS=()

emit_export() {
  local ordinal="$1"
  local fn="$2"

  [[ "$ordinal" =~ ^[0-9]+$ ]] || {
    echo "invalid ordinal for $fn: $ordinal" >&2
    exit 1
  }
  [[ -n "$fn" ]] || {
    echo "empty export name for ordinal $ordinal" >&2
    exit 1
  }
  if [[ -n "${SEEN_NAMES[$fn]:-}" ]]; then
    echo "duplicate export name: $fn" >&2
    exit 1
  fi
  if [[ -n "${SEEN_ORDINALS[$ordinal]:-}" ]]; then
    echo "duplicate export ordinal @$ordinal ($fn and ${SEEN_ORDINALS[$ordinal]})" >&2
    exit 1
  fi
  SEEN_NAMES[$fn]=1
  SEEN_ORDINALS[$ordinal]="$fn"

  if is_hooked "$fn"; then
    echo "    $fn @$ordinal"                  # exported from our code
  else
    echo "    $fn = $REAL_DLL.$fn @$ordinal"  # loader forwards straight through
  fi
}

{
  echo "; AUTO-GENERATED by generate_def.sh -- do not edit by hand."
  echo "; Shim proxy for winhttp.dll. Forwards to $REAL_DLL.dll. Ordinals preserved."
  echo "LIBRARY winhttp"
  echo "EXPORTS"
  ordinal=1
  while IFS= read -r fn; do
    fn="${fn%%$'\r'}"
    fn="${fn%%#*}"
    fn="${fn#"${fn%%[![:space:]]*}"}"
    fn="${fn%"${fn##*[![:space:]]}"}"
    [ -z "$fn" ] && continue
    if [[ "$fn" =~ ^([0-9]+)[[:space:]]+([^[:space:]]+)$ ]]; then
      emit_export "${BASH_REMATCH[1]}" "${BASH_REMATCH[2]}"
      ordinal=$((BASH_REMATCH[1] + 1))
    elif [[ "$fn" =~ ^([^[:space:]]+)[[:space:]]+@([0-9]+)$ ]]; then
      emit_export "${BASH_REMATCH[2]}" "${BASH_REMATCH[1]}"
      ordinal=$((BASH_REMATCH[2] + 1))
    else
      emit_export "$ordinal" "$fn"
      ordinal=$((ordinal + 1))
    fi
  done < "$IMPORTS"
} > "$OUT"

total=$(grep -cE '^    ' "$OUT")
fwd=$(grep -cE ' = ' "$OUT")
echo "wrote $OUT: $total exports ($fwd forwarded, $((total-fwd)) hooked)"
